USE facturaBonita;

ALTER TABLE facturas ADD COLUMN emisor_logo_posicion VARCHAR(10) NOT NULL DEFAULT 'left' AFTER emisor_logo_blanco;

CREATE TABLE IF NOT EXISTS portal_usuarios (id CHAR(36) PRIMARY KEY,nombre VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,empresa VARCHAR(160) NOT NULL,tipo_identificacion VARCHAR(2) NOT NULL,numero_identificacion VARBINARY(255) NOT NULL,correo_facturacion VARCHAR(160) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS portal_perfiles (usuario_id CHAR(36) PRIMARY KEY,nombre_comercial VARCHAR(160),actividad_economica VARCHAR(12),telefono VARCHAR(30),provincia VARCHAR(3),canton VARCHAR(3),distrito VARCHAR(3),otras_senas VARCHAR(255),logo LONGTEXT,logo_blanco LONGTEXT,logo_posicion ENUM('left','center','right') NOT NULL DEFAULT 'left',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_portal_perfil_usuario FOREIGN KEY(usuario_id) REFERENCES portal_usuarios(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS portal_sesiones (id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id CHAR(36) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_portal_sesion_usuario FOREIGN KEY(usuario_id) REFERENCES portal_usuarios(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS portal_ventas (id VARCHAR(24) PRIMARY KEY,usuario_id CHAR(36) NOT NULL,receptor_nombre VARCHAR(160) NOT NULL,receptor_tipo_id VARCHAR(2),receptor_numero_id VARBINARY(255),receptor_correo VARCHAR(160) NOT NULL,items_json LONGTEXT NOT NULL,subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,descuento DECIMAL(12,2) NOT NULL DEFAULT 0,impuesto DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL,moneda VARCHAR(3) NOT NULL DEFAULT 'CRC',estado VARCHAR(40) NOT NULL DEFAULT 'pendiente_pago',referencia_pago VARCHAR(100) NOT NULL UNIQUE,pago_payload LONGTEXT,factura_id VARCHAR(20),error_detalle TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_portal_venta_usuario FOREIGN KEY(usuario_id) REFERENCES portal_usuarios(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_portal_venta_factura FOREIGN KEY(factura_id) REFERENCES facturas(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS portal_integraciones (id BIGINT AUTO_INCREMENT PRIMARY KEY,venta_id VARCHAR(24) NOT NULL,servicio VARCHAR(100) NOT NULL,endpoint VARCHAR(1000),estado VARCHAR(30) NOT NULL DEFAULT 'pendiente',http_status INT,mensaje TEXT,request_json LONGTEXT,response_json LONGTEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_portal_integracion_venta FOREIGN KEY(venta_id) REFERENCES portal_ventas(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
